const gst = () => S.guitar || (S.guitar = {});
/* Guitar progression follows the same rule as the piano course: finish a lesson (or pass its module test)
   to unlock the next one. Lessons already finished always stay open. */
const gOrder = () => GMODS.reduce((a, m) => a.concat(m[1]), []);
const gDone = id => !!(gst()[id] || {}).done;
function gUnlocked(id) {
  const order = gOrder(), i = order.indexOf(id);
  return i <= 0 || gDone(id) || gDone(order[i - 1]);
}
function gNextLesson() { return gOrder().find(id => !gDone(id)) || null; }
function gDoneCount() { return gOrder().filter(gDone).length; }
function gChordSvg(name) {
  const f = GCH[name]; if (!f) return '';
  const W = 90, H = 108, x0 = 14, dx = 12.4, y0 = 22, dy = 15;
  let s = '<svg viewBox="0 0 ' + W + ' ' + H + '" width="90" height="108" role="img" aria-label="' + esc(name) + ' chord diagram"><g stroke="currentColor" fill="none" stroke-width="1">';
  for (let i = 0; i < 6; i++) s += '<line x1="' + (x0 + i * dx) + '" y1="' + y0 + '" x2="' + (x0 + i * dx) + '" y2="' + (y0 + 5 * dy) + '"/>';
  for (let j = 0; j <= 5; j++) s += '<line x1="' + x0 + '" y1="' + (y0 + j * dy) + '" x2="' + (x0 + 5 * dx) + '" y2="' + (y0 + j * dy) + '" stroke-width="' + (j === 0 ? 2.5 : 1) + '"/>';
  s += '</g><g fill="currentColor" font-size="9" text-anchor="middle">';
  f.forEach((fr, i) => { const x = x0 + i * dx; if (fr < 0) s += '<text x="' + x + '" y="15">×</text>'; else if (fr === 0) s += '<circle cx="' + x + '" cy="12" r="3" fill="none" stroke="currentColor"/>'; else s += '<circle cx="' + x + '" cy="' + (y0 + (fr - 0.5) * dy) + '" r="4.6"/>'; });
  return s + '</g><text x="' + (W / 2) + '" y="' + (H - 2) + '" font-size="11" text-anchor="middle" fill="currentColor" font-weight="700">' + esc(name) + '</text></svg>';
}
function gStrumEvents(name, t0, spread, down) {
  const f = GCH[name], notes = []; f.forEach((fr, i) => { if (fr >= 0) notes.push(GSTR[i] + fr); });
  const seq = down ? notes : notes.slice().reverse();
  return seq.map((m, i) => ({ t: t0 + i * spread, d: down ? 1.4 : 0.6, notes: [m], vel: down ? 0.7 : 0.5 }));
}
function gJamScript(j) {
  const ev = [], PAT = [[0, 1], [1, 1], [1.5, 0], [2.5, 0], [3, 1], [3.5, 0]];
  j.chords.forEach((c, bar) => { if (j.arp) { const f = GCH[c], b = f.findIndex(x => x >= 0); (j.pat === 'travis' ? [b, 4, (b + 2 <= 3 ? b + 2 : b + 1), 5, b, 4, (b + 2 <= 3 ? b + 2 : b + 1), 5] : [b, 3, 4, 5, 4, 3, 4, 5]).forEach((si, k) => { if (f[si] >= 0) ev.push({ t: bar * 4 + k * 0.5, d: 1.5, notes: [GSTR[si] + f[si]], vel: k % 2 === 0 ? 0.75 : 0.5 }); }); } else PAT.forEach(p => gStrumEvents(c, bar * 4 + p[0], 0.03, !!p[1]).forEach(e => ev.push(e))); });
  return { events: ev.concat(E.beatEvents({ beat: j.beat, swing: 0 }, j.chords.length)), bpm: j.bpm, total: j.chords.length * 4 };
}
