const GNEW = [
  { id: 'g11', title: 'Counting and the metronome', mins: 10, why: 'Steady time matters more than fast hands.', body: ['Count every bar as 1 e & a, 2 e & a, 3 e & a, 4 e & a. The numbers are beats, and the "&" is halfway between beats.', 'Set a metronome app to 60 BPM. Strum one down-strum on each beat, then two (down-up) on each beat.', 'Raise the speed by 5 BPM only after you can play 4 clean bars in a row at the current speed.'], chords: ['Em', 'Am'], jam: { chords: ['Em', 'Am', 'Em', 'Am'], beat: 'ballad', bpm: 60 }, play: ['Strum Em once per click for 4 bars', 'Strum down-up twice per click for 4 bars', 'Change Em to Am on beat 1 without stopping the count'], apply: 'Practise with a metronome for five minutes and write down the BPM you reached.', quiz: [gq('How many "&" counts are in one bar of 4/4 in eighth notes?', ['2', '4', '6', '8'], 1, '1 & 2 & 3 & 4 & has four "&" counts.'), gq('When should you raise the metronome speed?', ['When bored', 'After four clean bars at the current speed', 'Never', 'Every minute'], 1, 'Earn each speed first.'), gq('A metronome at 60 BPM clicks…', ['Once per second', 'Twice per second', 'Once per minute', 'Every 4 seconds'], 0, '60 clicks per minute is one per second.')] },
  { id: 'g12', title: 'Gospel groove in 12/8', mins: 12, why: 'The rolling slow feel runs through hymns and worship ballads.', body: ['12/8 has four beats and each beat splits into three: 1-2-3, 2-2-3, 3-2-3, 4-2-3. Say it as a rolling count.', 'Strum down on every number, or play down on 1 and the last of each group. Feel the swing.', 'Try it with the Slow worship beat, then play G, C and D in the same feel.'], chords: ['G', 'C', 'D'], jam: { chords: ['G', 'C', 'D', 'G'], beat: 'worship', bpm: 56 }, play: ['Count 1-2-3 2-2-3 3-2-3 4-2-3 aloud slowly', 'Strum down on each number while counting', 'Play G then C in 12/8 for four bars'], apply: 'Play G, C, D, G in 12/8 along with the app twice through.', quiz: [gq('How many subdivisions are in each beat of 12/8?', ['2', '3', '4', '6'], 1, 'Each beat has three.'), gq('What is the count of the second beat?', ['2-2-3', '2-3-4', '1-2-3', '2-4-6'], 0, 'Beat two reads 2-2-3.'), gq('12/8 is most common in…', ['Fast dance songs', 'Slow gospel and worship ballads', 'Marches', 'Reggae'], 1, 'It is the classic slow gospel feel.')] },
  { id: 'g13', title: 'Dynamics and palm muting', mins: 10, why: 'Soft verses and strong choruses move people.', body: ['Dynamics means loud and soft. Strum lightly with fewer strings in the verse, and fully with more energy in the chorus.', 'Palm muting: rest the edge of your strumming hand lightly on the strings next to the bridge. It gives a short, dull sound that adds drive.', 'Practise the same four chords three ways: very soft, normal and strong.'], chords: ['G', 'D', 'Em', 'C'], jam: { chords: ['G', 'D', 'Em', 'C'], beat: 'rock', bpm: 76 }, play: ['Strum G D Em C softly', 'Strum them strongly', 'Palm mute on the bass strings for one bar'], apply: 'Play a verse softly and a chorus strongly with the same four chords.', quiz: [gq('What are dynamics?', ['Changes in loudness', 'Changes in key', 'Tuning', 'A type of strings'], 0, 'Dynamics are loud and soft.'), gq('Where does the palm rest for palm muting?', ['By the bridge, on the strings', 'On the headstock', 'On the fretboard', 'Behind the nut'], 0, 'Beside the bridge.'), gq('When is a stronger strum most useful?', ['In the chorus for energy', 'Never', 'Only when tuning', 'In silence'], 0, 'Choruses lift the energy.')] },
  { id: 'g14', title: 'Sus chords: Dsus4, Asus2, Cadd9', mins: 10, why: 'These add the open, modern sound you hear in worship music.', body: ['A sus chord swaps the third for another note, so it sounds open and unresolved. Dsus4 and Asus2 are small changes from D and A.', 'Cadd9 adds the note D to C and has a bright worship sound. It is easy to reach from G.', 'Play D, then Dsus4, then D again. Hear the lift and the resolution.'], chords: ['D', 'Dsus4', 'Asus2', 'Cadd9'], jam: { chords: ['G', 'Cadd9', 'D', 'Dsus4'], beat: 'ballad', bpm: 64 }, play: ['Play D, then Dsus4, then D', 'Play A, then Asus2', 'Move from G to Cadd9 smoothly'], apply: 'Add Dsus4 to the end of a D chord in a song you know.', quiz: [gq('What does a sus chord replace?', ['The third', 'The root', 'The octave', 'Nothing'], 0, 'The third is replaced.'), gq('Which chord is a small change from D?', ['Dsus4', 'F', 'Bm', 'E7'], 0, 'One finger moves.'), gq('Cadd9 adds which note to C?', ['D', 'F', 'A', 'B'], 0, 'The ninth of C is D.')] },
  { id: 'g15', title: 'Chords in a key: G major', mins: 12, why: 'Knowing the family of chords in a key lets you play any song.', body: ['Every major key has seven chords. In G: G (1), Am (2m), Bm (3m), C (4), D (5), Em (6m) and F♯dim (7).', 'The major chords 1, 4 and 5 and the minors 2m, 3m and 6m are used most often.', 'Numbers work in any key: 1–5–6m–4 is G D Em C in G, and C G Am F in C.'], chords: ['G', 'Am', 'C', 'D', 'Em', 'Bm'], jam: { chords: ['G', 'C', 'Em', 'D'], beat: 'rock', bpm: 72 }, play: ['Say the chords of G major with their numbers', 'Play G, C, D, Em and Am in order', 'Play 1–4–5–1 in G'], apply: 'Write 1–5–6m–4 in the keys of G and C.', quiz: [gq('In G major, what is the 4 chord?', ['C', 'D', 'Em', 'Am'], 0, 'G A B C: C is the 4th.'), gq('In G major, what is 6m?', ['Em', 'Am', 'Bm', 'C'], 0, 'E is the sixth note.'), gq('Why use numbers instead of chord letters?', ['They work in any key', 'They are louder', 'They are required', 'They are shorter only'], 0, 'Numbers transpose easily.')] },
  { id: 'g16', title: 'Minor keys: E minor', mins: 10, why: 'Minor keys give you deeper, more emotional songs.', body: ['A minor key has a sadder, deeper mood. E minor is the easiest guitar minor key, and its chords are Em, Am, Bm, G, C and D.', 'Em is home (1m). Am is 4m, D is often the 5 chord, and G is the relative major.', 'Practise the loop Em – Am – D – G. Notice how Em feels like home.'], chords: ['Em', 'Am', 'D', 'G'], jam: { chords: ['Em', 'Am', 'D', 'G'], beat: 'worship', bpm: 58 }, play: ['Play Em – Am – D – G slowly', 'Play it with the slow worship beat', 'Hum the first note of a melody over Em'], apply: 'Compose a four-chord loop in Em in the Song Lab.', quiz: [gq('Which chord feels like home in Em?', ['Em', 'G', 'D', 'Am'], 0, 'Em is the 1m.'), gq('Which major key shares the same chords as Em?', ['G', 'D', 'F', 'A'], 0, 'G is the relative major.'), gq('What is the 4 chord in Em?', ['Am', 'D', 'G', 'C'], 0, 'A is the fourth note from E.')] },
  { id: 'g17', title: 'The key of A', mins: 10, why: 'A, D and E are easy open chords with a bright, strong sound.', body: ['A, D and E are 1, 4 and 5 in the key of A, and all three are open and easy.', 'E7 adds a bluesy pull back to A. Many gospel and blues songs live in this key.', 'Play A – D – E – A with a bright beat, then add E7 before returning to A.'], chords: ['A', 'D', 'E', 'E7'], jam: { chords: ['A', 'D', 'E', 'A'], beat: 'highlife', bpm: 84 }, play: ['Play A, D and E with clean strums', 'Change A to D for one minute', 'Play 1–4–5–1 in A'], apply: 'Play A D E A twice with the Highlife beat.', quiz: [gq('What are 1, 4 and 5 in the key of A?', ['A, D, E', 'A, C, G', 'A, B, E', 'A, F, G'], 0, 'A, D and E.'), gq('Which chord adds a bluesy pull to A?', ['E7', 'Dm', 'F', 'Bm'], 0, 'E7 pulls to A.'), gq('Is E major or minor in the key of A?', ['Major', 'Minor'], 0, 'The 5 chord is major here.')] },
  { id: 'g18', title: 'Reading tab', mins: 10, why: 'Tab is the quickest way to read riffs and melodies.', body: ['Tab shows six lines for the six strings, with the thinnest string (high e) on top. A number is the fret to press, and 0 is open.', 'Read left to right. Numbers stacked in a column are played together as a chord.', 'Example: stacked from top to bottom, 0 1 0 2 3 and nothing on the low E is a C chord.'], chords: ['C'], play: ['Find the six lines and say which string each is', 'Read the C chord from the tab description and play it', 'Write the tab of Em yourself'], apply: 'Write the tab of Am.', quiz: [gq('Which string is the top line of tab?', ['High e', 'Low E', 'A', 'D'], 0, 'The top line is the thinnest string.'), gq('What does a 0 mean?', ['Play the string open', 'Mute the string', 'Fret 10', 'Skip the string'], 0, 'Zero is an open string.'), gq('Numbers stacked in a column are…', ['Played together', 'Played one after another', 'Ignored', 'Rests'], 0, 'A column is a chord.')] },
  { id: 'g19', title: 'Fingerpicking', mins: 14, why: 'Fingerpicking turns the same chords into a gentle, flowing sound.', body: ['In fingerpicking your thumb plays the bass strings (E, A, D) and your index, middle and ring fingers play G, B and e.', 'Start with the pattern: bass, G, B, e, B, G, B, e (eight notes per bar). Keep each note even.', 'Try it on G, then Em, then C, with the slow ballad beat.'], chords: ['G', 'Em', 'C'], jam: { chords: ['G', 'Em', 'C', 'D'], beat: 'ballad', bpm: 60, arp: true }, play: ['Pluck the bass note with your thumb', 'Play the full eight-note pattern on G', 'Change from G to Em without breaking the pattern'], apply: 'Play G Em C D in the pattern for two minutes.', quiz: [gq('Which fingers play the thin strings?', ['Index, middle, ring', 'Only the thumb', 'Only the little finger', 'None'], 0, 'Three fingers pick the top strings.'), gq('What does the thumb play?', ['Bass strings', 'The thinnest string', 'Nothing', 'Only chords'], 0, 'The thumb plays the bass.'), gq('Fingerpicking suits…', ['Quiet verses and ballads', 'Only loud songs', 'Only fast songs', 'Only solos'], 0, 'It gives a soft, flowing sound.')] },
  { id: 'g20', title: 'Hammer-ons, pull-offs and slides', mins: 10, why: 'These small moves make simple chords sound alive.', body: ['A hammer-on: pluck a note, then press a higher fret with another finger, without plucking again. The strike makes the second note.', 'A pull-off: pluck a fretted note, then pull your finger away so the lower note sounds.', 'A slide moves one finger along the string from one fret to another. Use these to decorate chords.'], chords: ['Em', 'Asus2'], play: ['Hammer on from fret 0 to fret 2 on the A string', 'Pull off from fret 2 to fret 0', 'Slide from fret 2 to fret 4 on one string'], apply: 'Add a hammer-on to the start of an Em chord and play four bars.', quiz: [gq('In a hammer-on, how is the second note made?', ['By striking the string with a finger', 'By plucking again', 'By the capo', 'By muting'], 0, 'The finger strike sounds it.'), gq('A pull-off sounds…', ['The lower note', 'A higher note', 'No note', 'A chord'], 0, 'Releasing the finger lets the lower note ring.'), gq('A slide…', ['Moves along one string', 'Mutes the string', 'Changes the tuning', 'Removes a string'], 0, 'It glides between frets.')] },
  { id: 'g21', title: 'Song forms', mins: 10, why: 'Knowing the shape of a song tells you what comes next.', body: ['Most songs follow a form: Intro, Verse, Chorus, Verse, Chorus, Bridge, Chorus, Outro.', 'The verse tells the story, the chorus is the main message, and the bridge adds contrast with new chords or a new feel.', 'Change the feel between sections: a soft strum in the verse, a strong strum in the chorus.'], chords: ['G', 'D', 'Em', 'C'], jam: { chords: ['G', 'D', 'Em', 'C'], beat: 'rock', bpm: 76 }, play: ['Name the sections of a song you know', 'Play 8 bars as verse and 8 bars as chorus', 'Add a 2-bar intro'], apply: 'Use the Song Lab to build a verse, chorus and bridge with your four chords.', quiz: [gq('What does the bridge usually add?', ['Contrast', 'Nothing', 'A repeat', 'Silence'], 0, 'It adds contrast.'), gq('Which section usually carries the main message?', ['Chorus', 'Intro', 'Outro', 'Bridge'], 0, 'The chorus is the heart.'), gq('How can you show a chorus is different?', ['Strum stronger', 'Stop playing', 'Change key randomly', 'Play slower always'], 0, 'Dynamics show the change.')] },
  { id: 'g22', title: 'Accompanying a singer', mins: 10, why: 'Leading worship is about serving the voice, not showing off.', body: ['Your job is to support the voice: keep steady time, play softly under the singer, and leave space.', 'Choose a key that fits the singer. Use a capo to move the key without changing shapes.', 'Watch the leader, follow the dynamics, finish chords together, and count in the tempo before starting.'], chords: ['G', 'C', 'D'], jam: { chords: ['G', 'C', 'D', 'G'], beat: 'ballad', bpm: 66 }, play: ['Count in four beats aloud, then start together', 'Play G C D G softly', 'Finish the last chord with a clear stop'], apply: 'Accompany someone singing one verse, and ask for feedback.', quiz: [gq('What is your main job when accompanying?', ['Support the singer', 'Play the loudest', 'Play solos only', 'Change keys at random'], 0, 'Serve the voice.'), gq('How can you change key without changing shapes?', ['Use a capo', 'Retune everything', 'Buy a new guitar', 'You cannot'], 0, 'A capo raises the key.'), gq('Before starting a song you should…', ['Count in the tempo', 'Play fast', 'Stop the singer', 'Change strings'], 0, 'A count-in aligns everyone.')] },
  { id: 'g23', title: 'Capstone: lead a worship song', mins: 20, why: 'Put every skill together in one performance.', body: ['Choose a four-chord worship progression and play it for three minutes without stopping.', 'Use your skills: steady strum, dynamics, a sus chord or a hammer-on, and a change of feel between verse and chorus.', 'Record yourself on your phone, listen back, and note one thing to improve.'], chords: ['G', 'D', 'Em', 'C'], jam: { chords: ['G', 'D', 'Em', 'C'], beat: 'worship', bpm: 60 }, play: ['Play three minutes without stopping', 'Use two different strum feels', 'Add one sus chord or hammer-on'], apply: 'Record yourself and write one thing to improve.', quiz: [gq('What matters most in the capstone?', ['Steady time', 'Speed', 'Loudness', 'Never changing chords'], 0, 'Steady time carries the song.'), gq('How do you show the chorus is bigger?', ['Dynamics', 'Stopping', 'Tuning down', 'Changing strings'], 0, 'Play stronger.'), gq('What is a good way to improve?', ['Record and listen back', 'Never listen', 'Play only fast', 'Skip practice'], 0, 'Recordings show what to fix.')] }
];
GUITAR.push(...GNEW);
GUITAR.forEach(L => { const x = GX[L.id]; if (x) { Object.assign(L, x); if (x.more) L.quiz = L.quiz.concat(x.more); } });
Object.assign(GCH, { Am7: [-1, 0, 2, 0, 1, 0], Em7: [0, 2, 0, 0, 0, 0], Dm7: [-1, -1, 0, 2, 1, 1], Cmaj7: [-1, 3, 2, 0, 0, 0], Fmaj7: [-1, -1, 3, 2, 1, 0], Gmaj7: [3, 2, 0, 0, 0, 2], Dmaj7: [-1, -1, 0, 2, 2, 2], 'D/F#': [2, -1, 0, 2, 3, 2], 'G/B': [-1, 2, 0, 0, 3, 3], 'C/G': [3, 3, 2, 0, 1, 0], B7: [-1, 2, 1, 2, 0, 2], 'G (E shape)': [3, 5, 5, 4, 3, 3], 'B (A shape)': [-1, 2, 4, 4, 4, 2], 'C (A shape)': [-1, 3, 5, 5, 5, 3] });
const GQ = rows => rows.map(r => gq(r[0], r[1], r[2], r[3]));
const GNEW2 = [
  { id: 'g24', title: 'Sixteenth-note strumming', mins: 12, why: 'Sixteenth notes give a busy, driving feel that fits upbeat praise songs.', body: ['Count each beat as 1 e & a. Your hand moves down on the number and "&", and up on "e" and "a".', 'Keep the hand moving all the time, and only hit the strings on the beats you choose. The missed strums are called ghost strums.', 'Start at 60 BPM, then raise the speed by 5 BPM only after four clean bars.'], chords: ['G', 'C', 'D'], jam: { chords: ['G', 'C', 'G', 'D'], beat: 'rock', bpm: 84 }, play: ['Strum all sixteenths on one chord at 60 BPM', 'Keep the hand moving but hit only the 1, & and a of each beat', 'Change G to C with the same pattern'], apply: 'Play G C G D at 84 BPM along with the app.', quiz: GQ([['How many sixteenth notes are in one beat?', ['2', '3', '4', '8'], 2, 'Four: 1 e & a.'], ['Which part of the count is the down-strum on "&"?', ['Halfway through the beat', 'The start of the beat', 'The end of the bar', 'It is not played'], 0, 'The "&" falls halfway.'], ['What are ghost strums?', ['Moves that miss the strings to keep time', 'Muted tuning', 'Loud strums', 'Capo tricks'], 0, 'The hand moves but does not hit.']]) },
  { id: 'g25', title: 'Waltz and 6/8 strumming', mins: 10, why: 'Three-beat songs need their own strum, and many hymns use it.', body: ['In 3/4 (waltz) count 1 2 3. Play a bass note on 1, then strum down on 2 and 3.', 'In 6/8 count 1 2 3 4 5 6 with the strong beats on 1 and 4. A common strum is Down, Down-Up, Down, Down-Up.', 'Choose a slow tempo first and keep the accent on the first beat.'], chords: ['G', 'C', 'D'], play: ['Count 1 2 3 aloud and strum on each', 'Play bass-strum-strum on G for four bars', 'Play D, D-U, D, D-U in 6/8 on C'], apply: 'Play G, C, D, G in 3/4 for eight bars.', quiz: GQ([['How many beats are in 3/4?', ['2', '3', '4', '6'], 1, 'Three.'], ['Where is the strong beat in 3/4?', ['1', '2', '3', 'All'], 0, 'Beat 1.'], ['6/8 has strong beats on…', ['1 and 4', '2 and 5', '3 and 6', 'Only 1'], 0, 'Two groups of three.']]) },
  { id: 'g26', title: 'Chops and backbeat', mins: 10, why: 'A muted chop on 2 and 4 gives rhythm like a drummer.', body: ['A chop is a short, muted strum: strike the strings and release pressure at once, so the sound stops.', 'Chop on beats 2 and 4 (the backbeat) and strum open on 1 and 3. This works well with the Pop/rock and Afrobeat beats.', 'Practise with just one chord until the chop is crisp.'], chords: ['Em', 'D'], jam: { chords: ['Em', 'D', 'Em', 'D'], beat: 'afro', bpm: 96 }, play: ['Strum open on 1 and 3, chop on 2 and 4', 'Keep it going for one minute on Em', 'Change Em to D without breaking the backbeat'], apply: 'Play Em D Em D with the Afrobeat feel.', quiz: GQ([['Which beats do you chop?', ['2 and 4', '1 and 3', 'Only 1', 'All'], 0, 'The backbeat.'], ['What makes a chop?', ['Releasing pressure right after the strike', 'Pressing harder', 'Using a capo', 'Muting with the headstock'], 0, 'The sound stops quickly.'], ['Which beats from the app match this feel well?', ['Pop/rock or Afrobeat', 'No drums', 'Only worship', 'Silence'], 0, 'They have a strong backbeat.']]) },
  { id: 'g27', title: 'Major 7 and minor 7 chords', mins: 14, why: 'Seventh chords add the smooth sound heard in modern worship and gospel.', body: ['Cmaj7, Fmaj7, Gmaj7 and Dmaj7 have a soft, dreamy sound. Am7, Em7 and Dm7 are warm minor chords.', 'Many are small changes from chords you know: Am to Am7 lifts one finger, and Em to Em7 lifts another.', 'Play the loop Cmaj7 – Am7 – Dm7 – G7 and listen to how smoothly it moves.'], chords: ['Cmaj7', 'Fmaj7', 'Gmaj7', 'Am7', 'Em7', 'Dm7'], jam: { chords: ['Cmaj7', 'Am7', 'Dm7', 'G7'], beat: 'ballad', bpm: 66 }, drill: { a: 'Am7', b: 'Cmaj7', target: 18 }, play: ['Play Am, then Am7', 'Play Em, then Em7', 'Play Cmaj7 – Am7 – Dm7 – G7 slowly'], apply: 'Replace the chords of a four-chord song with the seventh versions.', quiz: GQ([['Which chord is the smoothest change from Am?', ['Am7', 'F', 'B', 'E7'], 0, 'Lift one finger.'], ['Which is a major seventh chord?', ['Cmaj7', 'Am7', 'Dm7', 'Em7'], 0, 'maj7 means major seventh.'], ['What mood do major sevenths give?', ['Soft and dreamy', 'Aggressive', 'Silent', 'Flat'], 0, 'They sound smooth.']]) },
  { id: 'g28', title: 'Slash chords and walking basses', mins: 12, why: 'Changing the bass note makes your chord changes flow like a pro.', body: ['A slash chord such as G/B means play G with B as the lowest note. The bass walks smoothly: G, B, C, D.', 'Use it between chords that are a step apart. G to G/B to C sounds like a walk up the scale.', 'Play the bass note first with your thumb, then strum the rest.'], chords: ['G', 'G/B', 'C', 'D/F#'], jam: { chords: ['G', 'G/B', 'C', 'D/F#'], beat: 'ballad', bpm: 64 }, play: ['Play G then G/B', 'Walk the bass G – B – C', 'Play G – G/B – C – D/F# smoothly'], apply: 'Add G/B between G and C in a song you know.', quiz: GQ([['In G/B, which note is lowest?', ['B', 'G', 'D', 'C'], 0, 'After the slash is the bass note.'], ['What do slash chords create?', ['A smooth moving bass', 'A louder sound', 'A new key', 'A capo'], 0, 'The bass walks.'], ['G/B comes between which chords?', ['G and C', 'D and A', 'E and F', 'None'], 0, 'B walks from G up to C.']]) },
  { id: 'g29', title: 'The key of C', mins: 12, why: 'C major uses easy chords and suits many singers.', body: ['In C: C (1), Dm (2m), Em (3m), F (4), G (5) and Am (6m). Most songs use 1, 4, 5 and 6m.', 'F is the hardest. Start with the easy Fmaj7 shape from the earlier lesson, then work toward the full barre.', 'Play 1–5–6m–4 as C G Am F, and play the same in G to hear that only the key changed.'], chords: ['C', 'G', 'Am', 'Fmaj7'], jam: { chords: ['C', 'G', 'Am', 'Fmaj7'], beat: 'ballad', bpm: 68 }, play: ['Say the chords of C with numbers', 'Play C G Am Fmaj7 slowly', 'Play 1–4–5–1 in C'], apply: 'Play the same song in G and in C and notice the difference.', quiz: GQ([['What is the 4 chord in C?', ['F', 'G', 'Am', 'Dm'], 0, 'C D E F.'], ['What is 6m in C?', ['Am', 'Em', 'Dm', 'Bm'], 0, 'A is the sixth note.'], ['Which chord is easier to start with than a full F?', ['Fmaj7', 'Bm', 'B7', 'E7'], 0, 'The open Fmaj7 shape.']]) },
  { id: 'g30', title: 'The key of D', mins: 12, why: 'D is a bright, singable key with strong open chords.', body: ['In D: D (1), Em (2m), F♯m (3m), G (4), A (5) and Bm (6m).', 'Play 1–5–6m–4 as D A Bm G. Bm is a barre shape, so go slowly or use a capo.', 'Compare D A Bm G with G D Em C: it is the same song with a capo on fret 5.'], chords: ['D', 'A', 'Bm', 'G'], jam: { chords: ['D', 'A', 'Bm', 'G'], beat: 'rock', bpm: 80 }, play: ['Say the chords of D with numbers', 'Play D A Bm G slowly', 'Play it again with a capo on fret 5 using G shapes'], apply: 'Pick a song you know and play it in D.', quiz: GQ([['What is the 5 chord in D?', ['A', 'G', 'Em', 'Bm'], 0, 'D E F♯ G A.'], ['What is 6m in D?', ['Bm', 'Em', 'F♯m', 'Am'], 0, 'B is the sixth note.'], ['A capo on fret 5 with G shapes gives which key?', ['C', 'D', 'A', 'E'], 0, 'Five semitones above G is C.']]) },
  { id: 'g31', title: 'E-shape barre chords', mins: 14, why: 'One shape moved along the neck gives you every major chord.', body: ['The F you learned is an E-shape barre. Move it up the neck and it becomes F♯, G, A♭ and more.', 'The note under your barre finger on the low E string names the chord. Fret 3 gives G.', 'Play the G barre (fret 3) and then F (fret 1) back to back.'], chords: ['F', 'G (E shape)'], drill: { a: 'F', b: 'G (E shape)', target: 8 }, play: ['Play F with the barre at fret 1', 'Slide the whole shape to fret 3 for G', 'Slide back and forth between the two'], apply: 'Play G barre – C – D in time for two minutes.', quiz: GQ([['What names an E-shape barre chord?', ['The note on the low E string under the barre', 'The thumb position', 'The capo', 'The pick'], 0, 'The root is on the low E string.'], ['Fret 3 on the low E string is…', ['G', 'A', 'F', 'B'], 0, 'E F F♯ G.'], ['What happens when you slide the shape up two frets?', ['The chord goes up two semitones', 'It becomes minor', 'It is muted', 'Nothing'], 0, 'Two frets are two semitones.']]) },
  { id: 'g32', title: 'A-shape barre chords', mins: 14, why: 'The second movable shape covers Bm, B and C quickly.', body: ['Barre across fret 2 with finger 1, and press three strings at fret 4 with fingers 2, 3 and 4 (or one flat finger).', 'The root is on the A string. Fret 2 gives B, fret 3 gives C.', 'Play B (A shape), then C (A shape), then Bm.'], chords: ['Bm', 'B (A shape)', 'C (A shape)'], play: ['Play Bm with the barre at fret 2', 'Play B major at fret 2 with fingers on fret 4', 'Slide to fret 3 for C'], apply: 'Play C (A shape) – G (E shape) – Am – F with a slow beat.', quiz: GQ([['Where is the root of the A-shape barre?', ['On the A string', 'On the low E string', 'On the high e string', 'On the capo'], 0, 'It is named by the A string.'], ['Fret 3 on the A string is…', ['C', 'B', 'D', 'A'], 0, 'A B C.'], ['Which is the minor A-shape barre here?', ['Bm', 'B', 'C', 'G'], 0, 'Bm.']]) },
  { id: 'g33', title: 'Moving a progression to any key', mins: 14, why: 'With barre chords and numbers you can play any song in any key.', body: ['Write the progression as numbers, then find the chords in your key. 1–5–6m–4 is G D Em C in G, F C Dm B♭ in F, and A E F♯m D in A.', 'A capo is the quick method. Barre chords are the flexible method. Mix them when needed.', 'Choose the key to match the singer, not the easiest chords.'], chords: ['G', 'D', 'Em', 'C'], jam: { chords: ['G', 'D', 'Em', 'C'], beat: 'worship', bpm: 60 }, play: ['Write 1–5–6m–4 in C, D and A', 'Play it in G with open chords', 'Play it again with a capo on fret 2'], apply: 'Choose a key that fits your voice and play 1–5–6m–4 in it.', quiz: GQ([['What are 1–5–6m–4 in F?', ['F C Dm B♭', 'F G Am C', 'F B♭ C Dm', 'F D G A'], 0, 'F G A B♭: 5 is C, 6m is Dm, 4 is B♭.'], ['What are 1–5–6m–4 in A?', ['A E F♯m D', 'A D E Bm', 'A C D E', 'A B C D'], 0, 'E is 5, F♯m is 6m, D is 4.'], ['How do you pick the key?', ['To suit the singer', 'Always G', 'Always C', 'At random'], 0, 'Serve the voice.']]) },
  { id: 'g34', title: 'The minor pentatonic scale', mins: 14, why: 'This five-note scale is the foundation of leads and solos.', body: ['The A minor pentatonic scale is A C D E G. On the guitar, box 1 starts at fret 5. Play low to high, then back.', 'Use alternate picking (down-up) and keep the notes even. Each fret number below is the fret you press.', 'Improvise: pick any note in the box over an Am chord, and finish on A.'], tab: ['e|--5--8--', 'B|--5--8--', 'G|--5--7--', 'D|--5--7--', 'A|--5--7--', 'E|--5--8--'], notes: [45, 48, 50, 52, 55, 57, 60, 62, 64, 67, 69, 72], play: ['Play the scale up and down slowly', 'Play it with a metronome at 60 BPM', 'Improvise four bars over an Am chord'], apply: 'Improvise for two minutes over the app playing Am.', quiz: GQ([['How many notes are in a pentatonic scale?', ['5', '6', '7', '8'], 0, 'Penta means five.'], ['Which fret does box 1 start on in Am?', ['5', '2', '9', '12'], 0, 'The root A is at fret 5.'], ['Which picking style helps keep time?', ['Alternate (down-up)', 'Only down', 'Only up', 'Thumb only'], 0, 'It stays even.']]) },
  { id: 'g35', title: 'Playing a melody by ear', mins: 12, why: 'Finding the tune on your own makes you a complete musician.', body: ['Start with a song you know very well. Hum the first note and find it on one string.', 'Use the pentatonic box, move one fret at a time, and listen for steps up and down. The first note is often the home note.', 'Write the notes as numbers (1 2 3...) so you can play them in any key.'], chords: ['G', 'C', 'D'], play: ['Hum the first note and find it on the high e string', 'Play the first four notes of the melody', 'Add the chords under it'], apply: 'Find the melody of one hymn or worship song by ear and write it as numbers.', quiz: GQ([['Where do you start finding a melody?', ['The first note you hum', 'The last chord', 'The tuner', 'The capo'], 0, 'Start with the first note.'], ['Why write melodies as numbers?', ['They work in any key', 'They are louder', 'They are required', 'They look nicer'], 0, 'Numbers transpose.'], ['Which scale helps you find notes?', ['The pentatonic box', 'Chromatic only', 'No scale', 'The octave'], 0, 'It narrows the choices.']]) },
  { id: 'g36', title: 'Gospel turnarounds: 1–6m–2m–5', mins: 14, why: 'This loop is the engine behind many gospel and standards.', body: ['In G: G (1), Em (6m), Am (2m), D7 (5). Each chord leads naturally to the next, and D7 pulls home to G.', 'Play the loop slowly, then add a shuffle strum. Try putting a bass walk between chords.', 'Use it as the last two bars of a verse to return to the start.'], chords: ['G', 'Em', 'Am', 'D7'], jam: { chords: ['G', 'Em', 'Am', 'D7'], beat: 'shuffle', bpm: 76 }, drill: { a: 'Em', b: 'Am', target: 20 }, play: ['Play G Em Am D7 slowly four times', 'Play it with the gospel shuffle beat', 'Add a walk-up from D7 to G'], apply: 'Use 1–6m–2m–5 to end a song you know.', quiz: GQ([['In G, what are 6m and 2m?', ['Em and Am', 'Am and Em', 'D and C', 'C and D'], 0, 'E is 6m and A is 2m.'], ['What does D7 want to do?', ['Return to G', 'Stay put', 'Go to F', 'Mute'], 0, 'V7 resolves to I.'], ['Where do turnarounds often go?', ['At the end of a section', 'Never', 'Before the tuning', 'In the intro only'], 0, 'They lead back to the start.']]) },
  { id: 'g37', title: 'The amen: IV to I', mins: 10, why: 'The "amen" cadence is one of the most heartfelt endings in gospel.', body: ['The amen cadence moves from the IV chord to the I chord. In G that is C to G.', 'Play it softly and let the last chord ring. Use dynamics: grow slightly, then settle.', 'Practise it at the end of every progression you play.'], chords: ['C', 'G'], jam: { chords: ['G', 'D', 'C', 'G'], beat: 'ballad', bpm: 56 }, play: ['Play C then G with a soft strum', 'Let the last chord ring for four beats', 'Add the amen after G D Em C'], apply: 'End a worship song with an amen cadence.', quiz: GQ([['What is the amen cadence?', ['IV to I', 'V to I', 'I to V', 'ii to V'], 0, 'IV to I.'], ['In G, which chord is IV?', ['C', 'D', 'Em', 'Am'], 0, 'C is the 4th.'], ['How should you play it?', ['Softly, letting the last chord ring', 'As fast as possible', 'With a chop', 'Muted'], 0, 'It is reverent and calm.']]) },
  { id: 'g38', title: 'Gospel shuffle and praise strums', mins: 12, why: 'The right feel changes a song from calm to joyful.', body: ['The shuffle uses a long-short swing. Count 1 and-a 2 and-a and strum on the long parts.', 'A praise strum is fast and bright: down on every beat, with strong chops on 2 and 4 and quick up-strums between.', 'Use the Gospel shuffle and Fast praise beats in the app to practise.'], chords: ['G', 'C', 'D'], jam: { chords: ['G', 'C', 'G', 'D'], beat: 'praise', bpm: 118 }, play: ['Play the shuffle on G for one minute', 'Play the fast praise strum on G C G D', 'Change the feel in the middle of a song'], apply: 'Play the same song as a slow ballad and then as a fast praise.', quiz: GQ([['Which beat feels like a long-short swing?', ['Gospel shuffle', 'Fast praise', 'No drums', 'Reggae'], 0, 'The shuffle swings.'], ['Which beats get strong chops in a praise strum?', ['2 and 4', '1 and 3', 'Only 1', 'None'], 0, 'The backbeat.'], ['How can you change the mood of a song?', ['Change the feel and strum', 'Change the title', 'Mute the strings', 'Change the capo only'], 0, 'Feel shapes mood.']]) },
  { id: 'g39', title: 'Writing a song with the Song Lab', mins: 16, why: 'Writing your own songs puts your skills to real use.', body: ['Start with a short message. Write one sentence for the chorus and make it simple to remember.', 'Pick four chords in the Song Lab, choose a beat, and play the loop. Hum a melody until a tune fits.', 'Write a verse that tells the story, add a chorus that carries the message, and record it on your phone.'], chords: ['G', 'D', 'Em', 'C'], jam: { chords: ['G', 'D', 'Em', 'C'], beat: 'ballad', bpm: 66 }, play: ['Choose your four chords and beat in the Song Lab', 'Hum a melody over the loop until one fits', 'Write the first two lines of lyrics'], apply: 'Finish a verse and chorus and play them for someone.', quiz: GQ([['What should a chorus be?', ['Simple and memorable', 'Very long', 'Silent', 'Random'], 0, 'People must be able to sing it back.'], ['Where do you build the loop?', ['The Song Lab', 'The tuner', 'The capo', 'The quiz'], 0, 'Use the Song Lab.'], ['What does the verse do?', ['Tells the story', 'Repeats the chorus', 'Ends the song', 'Sets the tuning'], 0, 'It builds the message.']]) },
  { id: 'g40', title: 'Leading a set', mins: 14, why: 'Planning a set well helps the whole group worship together.', body: ['Choose songs in keys that flow: end one song on a chord that links to the next. Keep keys close and tempos varied.', 'Plan the start, the build and the quiet moment. Practise the transitions as much as the songs.', 'Count in clearly, watch the leader, and be ready to repeat a section.'], chords: ['G', 'D', 'Em', 'C'], jam: { chords: ['G', 'D', 'Em', 'C'], beat: 'worship', bpm: 62 }, play: ['List three songs in related keys', 'Practise the link between song one and two', 'Play a count-in and start together'], apply: 'Write a three-song set with the key and tempo of each.', quiz: GQ([['What helps songs flow in a set?', ['Close keys and planned transitions', 'Random keys', 'No plan', 'Only fast songs'], 0, 'Plan the links.'], ['What should you do before each song?', ['Count in clearly', 'Tune loudly', 'Walk away', 'Change strings'], 0, 'A clear count-in unites everyone.'], ['Who do you watch during the set?', ['The leader', 'Nobody', 'The floor', 'Your phone'], 0, 'Stay with the leader.']]) },
  { id: 'g41', title: 'Capstone II: perform a three-song set', mins: 30, why: 'The final test brings every skill together.', body: ['Prepare three songs in different feels: a fingerpicked ballad, a gospel shuffle and a fast praise.', 'Include a sus chord, a slash chord, a barre chord and a turnaround across the set. Use dynamics in every song.', 'Perform the set without stopping, record it, listen back and write down three strengths and one thing to improve.'], chords: ['G', 'Em', 'C', 'D'], jam: { chords: ['G', 'Em', 'C', 'D'], beat: 'shuffle', bpm: 76 }, play: ['Play all three songs without stopping', 'Use at least one sus chord and one barre chord', 'Record the set and listen back'], apply: 'Perform the set for a friend or the club and ask for feedback.', quiz: GQ([['What should the three songs have?', ['Different feels', 'The same feel', 'No chords', 'No rhythm'], 0, 'Contrast keeps the set alive.'], ['What do you do after performing?', ['Listen back and note strengths and one fix', 'Never review', 'Delete it', 'Play louder'], 0, 'Reflection builds skill.'], ['What carries every song?', ['Steady time', 'Speed', 'Volume only', 'Capo changes'], 0, 'Time first.']]) }
];
