GMODS.push(['8. Rhythm II', ['g24', 'g25', 'g26']], ['9. Chord vocabulary II', ['g27', 'g28', 'g29', 'g30']], ['10. Barre chords', ['g31', 'g32', 'g33']], ['11. Lead and melody', ['g34', 'g35']], ['12. Gospel guitar', ['g36', 'g37', 'g38']], ['13. Writing and performing', ['g39', 'g40', 'g41']]);

/* ---- stage 2: deeper lessons, ear training, tuner, test-outs, daily practice ---- */
const GSN = ['low E', 'A', 'D', 'G', 'B', 'high e'], GTESTS = {};
const gFind = id => GUITAR.find(x => x.id === id) || GTESTS[id];
const gShuf = a => a.slice().sort(() => Math.random() - 0.5);
function gWalk(c) { return GCH[c].map((fr, i) => '<li><b>' + GSN[i] + ':</b> ' + (fr < 0 ? 'do not play' : fr === 0 ? 'open' : 'press fret ' + fr) + '</li>').join(''); }
function gAutoQ(L) {
  const out = [];
  (L.chords || []).filter(c => GCH[c]).slice(0, 2).forEach((c, k) => {
    const f = GCH[c];
    if (k === 0) {
      const n = f.filter(x => x >= 0).length, o = [...new Set([n, n - 1, n + 1, n - 2, n + 2])].filter(x => x >= 1 && x <= 6).slice(0, 4).sort((a, b) => a - b);
      if (o.indexOf(n) < 0) o[0] = n;
      out.push(gq('How many strings do you play in ' + c + '?', o.map(String), o.indexOf(n), 'You play ' + n + ' strings in ' + c + '.'));
    } else {
      const mi = f.findIndex(x => x < 0);
      if (mi >= 0) {
        const pl = f.map((x, i) => i).filter(i => f[i] >= 0).slice(0, 3), idx = [mi].concat(pl).sort((a, b) => a - b);
        out.push(gq('Which string do you NOT play in ' + c + '?', idx.map(i => GSN[i]), idx.indexOf(mi), 'The ' + GSN[mi] + ' string is muted or skipped in ' + c + '.'));
      } else {
        const si = f.findIndex(x => x > 0);
        if (si >= 0) { const fr = f[si], o = [...new Set([fr, fr + 1, fr + 2, Math.max(1, fr - 1)])].sort((a, b) => a - b).slice(0, 4); if (o.indexOf(fr) < 0) o[0] = fr; out.push(gq('Which fret do you press on the ' + GSN[si] + ' string in ' + c + '?', o.map(String), o.indexOf(fr), 'Fret ' + fr + ' on the ' + GSN[si] + ' string.')); }
      }
    }
  });
  return out;
}
GUITAR.forEach(L => { if (!L._auto) { L._auto = 1; L.quiz = L.quiz.concat(gAutoQ(L)); } });
/* ear training */
let gEar = { mode: 'qual', cur: null, ans: null };
const GEAR_MAJ = ['G', 'C', 'D', 'A', 'E'], GEAR_MIN = ['Em', 'Am', 'Dm'];
function gEarNew() { const pool = gEar.mode === 'qual' ? GEAR_MAJ.concat(GEAR_MIN) : GEAR_MAJ.concat(GEAR_MIN); gEar.cur = pool[Math.floor(Math.random() * pool.length)]; gEar.ans = null; gEar.opts = gEar.mode === 'qual' ? ['Major', 'Minor'] : gShuf([gEar.cur].concat(gShuf(pool.filter(x => x !== gEar.cur)).slice(0, 3))); }
function viewGEar() {
  if (!gEar.cur) gEarNew();
  const e = (gst().ear = gst().ear || { n: 0, ok: 0 }), c = gEar.cur, isMin = GEAR_MIN.indexOf(c) >= 0;
  return { html: '<div class="screen"><div class="pagehead"><button class="btn ghost sm" type="button" data-act="gback">' + icon('back') + 'Guitar course</button><h1>Guitar ear training</h1><p class="muted">Listen to the chord, then answer. Score so far: ' + e.ok + ' of ' + e.n + ' correct.</p></div>' +
    '<section class="card"><div class="row wrap"><button class="btn ' + (gEar.mode === 'qual' ? 'primary' : 'ghost') + '" type="button" data-act="gearmode" data-m="qual">Major or minor?</button><button class="btn ' + (gEar.mode === 'name' ? 'primary' : 'ghost') + '" type="button" data-act="gearmode" data-m="name">Which chord?</button></div></section>' +
    '<section class="card"><button class="btn primary lg" type="button" data-act="gearplay">' + icon('play') + 'Play the chord</button><div class="row wrap" style="margin-top:.8rem">' + gEar.opts.map(o => '<button class="btn ghost" type="button" data-act="gearans" data-o="' + o + '"' + (gEar.ans ? ' disabled' : '') + '>' + o + '</button>').join('') + '</div>' +
    (gEar.ans ? '<p aria-live="polite"><b>' + (gEar.ans === 'ok' ? 'Correct.' : 'Not quite.') + '</b> It was ' + c + ' (' + (isMin ? 'minor' : 'major') + '). ' + gChordSvg(c) + '</p><button class="btn primary" type="button" data-act="gearnext">Next chord</button>' : '') + '</section></div>' };
}
/* tuner */
let gTun = null;
const GTARGET = [82.41, 110, 146.83, 196, 246.94, 329.63];
function gTunStop() { if (gTun) { clearInterval(gTun.iv); try { gTun.stream.getTracks().forEach(t => t.stop()); gTun.ac.close(); } catch (e) { /* ignore */ } gTun = null; } }
function gPitch(buf, sr) {
  let rms = 0; for (let i = 0; i < buf.length; i++) rms += buf[i] * buf[i]; rms = Math.sqrt(rms / buf.length); if (rms < 0.01) return -1;
  const N = 2048, lo = Math.floor(sr / 400), hi = Math.floor(sr / 70), corr = new Float32Array(hi + 2); let best = 0;
  for (let lag = lo; lag <= hi; lag++) { let s = 0, e1 = 0, e2 = 0; for (let i = 0; i < N; i++) { const a = buf[i], b = buf[i + lag]; s += a * b; e1 += a * a; e2 += b * b; } corr[lag] = s / Math.sqrt(e1 * e2 + 1e-9); if (corr[lag] > best) best = corr[lag]; }
  if (best < 0.8) return -1;
  for (let lag = lo + 1; lag < hi; lag++) if (corr[lag] > 0.9 * best && corr[lag] >= corr[lag - 1] && corr[lag] >= corr[lag + 1]) { const d = corr[lag - 1] - 2 * corr[lag] + corr[lag + 1], sh = d ? 0.5 * (corr[lag - 1] - corr[lag + 1]) / d : 0; return sr / (lag + sh); }
  return -1;
}
function viewGTuner() {
  return { html: '<div class="screen"><div class="pagehead"><button class="btn ghost sm" type="button" data-act="gback">' + icon('back') + 'Guitar course</button><h1>Guitar tuner</h1><p class="muted">Pluck one open string at a time, in a quiet room. The tuner listens through your microphone and shows how far off the string is.</p></div>' +
    '<section class="card"><button class="btn primary lg" type="button" id="gtunbtn" data-act="gtunstart">Start the tuner</button><p class="mono" style="font-size:2rem;margin:.6rem 0" id="gtunnote">–</p><p id="gtunmsg" aria-live="polite" class="muted">Targets: E2 82.4, A2 110, D3 146.8, G3 196, B3 246.9, e4 329.6 Hz.</p><div style="height:14px;background:var(--line);border-radius:7px;position:relative"><div id="gtunneedle" style="position:absolute;left:50%;top:-3px;width:6px;height:20px;background:var(--accent);border-radius:3px;transform:translateX(-50%)"></div></div><p class="tiny">Left of centre means flat (tune up). Right means sharp (tune down).</p></section></div>', mount() { return gTunStop; } };
}

const GNEW3 = [
  { id: 'g42', title: 'Travis picking', mins: 14, why: 'An alternating thumb bass under a steady melody gives the classic folk and gospel fingerstyle sound.', body: ['The thumb alternates between two bass strings (the root and the next lower string or the fifth) in a steady rhythm. The fingers pick the high strings in between.', 'Start with the thumb alone: root, other bass, root, other bass. Keep it even, like a marching beat.', 'Add the fingers on the B and high e strings. Slow down until the thumb never stops.'], chords: ['G', 'C', 'D'], jam: { chords: ['G', 'C', 'G', 'D'], beat: 'ballad', bpm: 62, arp: true, pat: 'travis' }, play: ['Play only the alternating thumb on G for one minute', 'Add the B and high e fingers on top', 'Change G to C without breaking the thumb'], apply: 'Play G C G D in Travis picking at 62 BPM along with the app.', quiz: GQ([['What does the thumb do in Travis picking?', ['Alternates between bass strings', 'Plays only the top string', 'Stays still', 'Mutes the strings'], 0, 'It keeps a steady alternating bass.'], ['What should you slow down until you can do?', ['Never stop the thumb', 'Play louder', 'Skip the fingers', 'Use a pick'], 0, 'The thumb must stay steady.'], ['Which strings do the fingers pick?', ['The high strings', 'The low E only', 'All six', 'None'], 0, 'B and high e.']]) },
  { id: 'g43', title: 'Hybrid strumming and picking', mins: 12, why: 'Mixing a bass note with a strum gives you a full sound by yourself.', body: ['Play the bass note of the chord on beat 1 with your thumb or pick, then strum the rest of the chord on 2, 3 and 4.', 'For G the bass is the low E, for C the A string, for D the D string. This is called a boom-chick pattern.', 'Alternate the bass note between root and fifth to add movement. Keep the strum soft and the bass clear.'], chords: ['G', 'C', 'D'], jam: { chords: ['G', 'C', 'G', 'D'], beat: 'rock', bpm: 80 }, play: ['Play bass then strum on G for four bars', 'Do the same on C and D', 'Alternate root and fifth in the bass'], apply: 'Play a verse with boom-chick and a chorus with a full strum.', quiz: GQ([['What is a boom-chick pattern?', ['Bass note then a strum', 'Only strumming', 'Only picking', 'A capo trick'], 0, 'Boom is the bass, chick is the strum.'], ['Where is the bass of C?', ['The A string', 'The low E', 'The high e', 'The B string'], 0, 'C is played from the A string.'], ['Why alternate root and fifth?', ['To add movement', 'To tune the guitar', 'To play quieter', 'To change key'], 0, 'It stops the bass sounding static.']]) },
  { id: 'g44', title: 'The CAGED system', mins: 16, why: 'Five shapes cover the whole fretboard, and you already know them.', body: ['The open chords C, A, G, E and D are the five shapes. Each one can be moved up the neck with a barre and still be the same shape.', 'The shapes connect in the order C – A – G – E – D, and then repeat. A G chord can be played as a G shape, an E shape (barre at fret 3), and more.', 'Learn to see one chord in several places. This lets you play in any position and choose the sound you want.'], chords: ['C', 'A', 'G', 'E', 'D'], play: ['Name the five CAGED shapes in order', 'Play G as the open shape and as the E-shape barre at fret 3', 'Find another place to play a C chord using an A shape at fret 3'], apply: 'Play a G chord in three different places on the neck.', quiz: GQ([['What do the letters CAGED stand for?', ['The five open chord shapes', 'Five scales', 'Five keys', 'Five strings'], 0, 'C, A, G, E and D.'], ['What can you do with each shape?', ['Move it up the neck with a barre', 'Nothing', 'Only play it open', 'Only play it muted'], 0, 'Shapes move.'], ['Why learn it?', ['To play one chord in many places', 'To play louder', 'To tune faster', 'To avoid practice'], 0, 'It opens the whole neck.']]) },
  { id: 'g45', title: 'Building chords from scales', mins: 14, why: 'Once you know how chords are built you can create your own shapes.', body: ['A major scale has seven notes. A triad uses the 1st, 3rd and 5th notes. In G major that is G, B and D, which is a G chord.', 'For a minor triad the third is lowered by one semitone: E, G, B makes Em.', 'Look at your open chords and find these three notes in each. Doubling a note changes the sound but not the chord.'], chords: ['G', 'Em', 'C'], play: ['Name the three notes of G, C and Em', 'Find the G, B and D on the guitar neck', 'Lower the B in G to B♭ and hear the minor sound'], apply: 'Write the 1-3-5 notes of D, A and E major chords.', quiz: GQ([['Which notes make a G major triad?', ['G B D', 'G C E', 'G A B', 'G D F'], 0, 'The 1st, 3rd and 5th.'], ['What changes in a minor triad?', ['The third is lowered', 'The root changes', 'The fifth is removed', 'Nothing'], 0, 'The third drops a semitone.'], ['What makes Em?', ['E G B', 'E A B', 'E F G', 'E G A'], 0, 'E, G and B.']]) },
  { id: 'g46', title: 'The circle of fifths', mins: 12, why: 'This map shows which chords belong together in every key.', body: ['The circle of fifths goes C, G, D, A, E, B, and so on. Each step adds one sharp. Moving clockwise by five notes gives the next key.', 'Neighbours on the circle share most of their chords. Keys of G, C and D sit next to each other and share chords you already know.', 'The key to the left is the IV chord and the key to the right is the V chord of the home key.'], chords: ['G', 'C', 'D'], play: ['Say the circle clockwise from C', 'Say the IV and V chord for G, C and D', 'Play G C D G in each of the three keys using the right capo'], apply: 'Write the IV and V chords for A and E major.', quiz: GQ([['Which key comes after C on the circle going clockwise?', ['G', 'F', 'D', 'A'], 0, 'C then G then D.'], ['In G, which keys are the IV and V chords?', ['C and D', 'D and A', 'F and C', 'A and E'], 0, 'C is IV and D is V.'], ['What is added each step clockwise?', ['One sharp', 'One flat', 'A string', 'A beat'], 0, 'Each step adds one sharp.']]) },
  { id: 'g47', title: 'The major pentatonic scale', mins: 14, why: 'The happy, bright sound of leads in gospel, country and rock.', body: ['The G major pentatonic is G A B D E. In open position, play the fret numbers shown below from the low E string up.', 'It uses the same shape as the minor pentatonic but starts from a different note. It sounds bright and joyful.', 'Improvise over G, C and D using only these notes. Land on G at the end.'], tab: ['e|--0--3--', 'B|--0--3--', 'G|--0--2--', 'D|--0--2--', 'A|--0--2--', 'E|--0--3--'], notes: [40, 43, 45, 47, 50, 52, 55, 57, 59, 62, 64, 67], jam: { chords: ['G', 'C', 'G', 'D'], beat: 'rock', bpm: 76 }, play: ['Play the scale up and down slowly', 'Play it with the click at 60 BPM', 'Improvise four bars over G'], apply: 'Improvise for two minutes along with the app on G C G D.', quiz: GQ([['Which notes are in G major pentatonic?', ['G A B D E', 'G B C D F', 'G A C D F', 'G B D E F'], 0, 'G, A, B, D, E.'], ['How does it sound?', ['Bright and joyful', 'Dark', 'Dissonant', 'Silent'], 0, 'Major pentatonic is bright.'], ['Where should you finish a phrase?', ['On G', 'On a random note', 'On a muted string', 'On F'], 0, 'End on the home note.']]) },
  { id: 'g48', title: 'The 12-bar blues in E', mins: 14, why: 'The blues form is the root of gospel, rock and many worship turnarounds.', body: ['The 12-bar blues uses three chords: I (E7), IV (A7) and V (B7). The form is 4 bars of E7, 2 of A7, 2 of E7, then B7, A7, E7 and B7.', 'Play it with a shuffle feel. The seventh chords give the bluesy sound.', 'Count the bars carefully. Knowing where you are in the 12 bars is the whole skill.'], chords: ['E7', 'A7', 'B7'], jam: { chords: ['E7', 'E7', 'E7', 'E7', 'A7', 'A7', 'E7', 'E7', 'B7', 'A7', 'E7', 'B7'], beat: 'shuffle', bpm: 84 }, play: ['Play four bars of E7, two of A7, and two of E7', 'Add B7, A7, E7 and B7 for the last four bars', 'Play the whole twelve bars three times without stopping'], apply: 'Play the 12-bar blues along with the app twice through.', quiz: GQ([['How many bars is the blues form?', ['12', '8', '16', '10'], 0, 'Twelve bars.'], ['Which chords make the blues in E?', ['E7, A7, B7', 'E, F, G', 'Em, Am, Bm', 'E, C, D'], 0, 'I, IV and V in E.'], ['How many bars is the I chord at the start?', ['4', '2', '1', '8'], 0, 'Four bars of E7.']]) },
  { id: 'g49', title: 'Reggae skank', mins: 10, why: 'A short upstroke on the off-beat gives the relaxed reggae groove.', body: ['In reggae the guitar plays a short, muted chord on the off-beats ("&" of each beat), called the skank. The drums are on beat 3.', 'Use only the top three or four strings and chop quickly. Keep the hand loose.', 'Practise on Am and G with the Reggae one-drop beat.'], chords: ['Am', 'G', 'F'], jam: { chords: ['Am', 'G', 'F', 'G'], beat: 'reggae', bpm: 76 }, play: ['Chop on the "&" of each beat on Am', 'Keep it going for two minutes', 'Change Am to G on beat 1'], apply: 'Play Am G F G with the reggae feel along with the app.', quiz: GQ([['Where does the skank fall?', ['On the off-beats', 'On beat 1 only', 'Nowhere', 'On every beat'], 0, 'The "&" of each beat.'], ['How is the chord played?', ['Short and muted', 'Long and loud', 'Fingerpicked', 'Open ringing'], 0, 'It is chopped quickly.'], ['Which app beat fits it?', ['Reggae one-drop', 'Fast praise', 'No drums', 'Slow ballad'], 0, 'The reggae beat.']]) },
  { id: 'g50', title: 'Highlife and Afrobeat guitar', mins: 14, why: 'Bright, interlocking patterns are the heartbeat of West and Central African music.', body: ['Highlife guitar plays short, ringing notes that dance above the bass. Pick two or three strings at a time and keep the notes crisp.', 'Afrobeat uses repeating patterns that lock with the drums. Strum short, muted chords on the off-beats and let one note ring.', 'Keep the pattern steady for minutes. The groove builds by repeating, not by changing.'], chords: ['A', 'D', 'E'], jam: { chords: ['A', 'D', 'E', 'A'], beat: 'highlife', bpm: 92 }, play: ['Pick the top three strings of A in a steady pattern', 'Keep a muted off-beat strum going for two minutes', 'Play A D E A with the highlife beat'], apply: 'Make your own two-bar highlife pattern and repeat it for a minute.', quiz: GQ([['What matters most in these grooves?', ['Steady repetition', 'Speed', 'Volume', 'Changing every bar'], 0, 'The groove builds by repeating.'], ['How are highlife notes played?', ['Short and crisp', 'Long and held', 'Muted always', 'Slowly'], 0, 'Crisp notes dance above the bass.'], ['What do you lock with?', ['The drums', 'The tuner', 'The capo', 'The audience'], 0, 'The guitar and drums fit together.']]) },
  { id: 'g51', title: 'Arranging a hymn in 3/4', mins: 14, why: 'Hymns are the heart of church music, and a good arrangement makes them shine.', body: ['Many hymns are in 3/4 or 4/4. Choose a key that suits the singers, then use simple chords: I, IV and V.', 'In 3/4 play a bass note on beat 1 and soft strums on 2 and 3. Add a walk-up of bass notes between chords.', 'Keep the arrangement simple and let the words carry the song.'], chords: ['G', 'C', 'D'], play: ['Play G, C, D, G in 3/4 with bass and strums', 'Walk the bass from G to C between bars', 'Soften the strum under the words'], apply: 'Arrange a hymn you know using only G, C and D.', quiz: GQ([['What chords suit a simple hymn?', ['I, IV and V', 'Only sevenths', 'Only barre chords', 'No chords'], 0, 'Simple chords suit a hymn.'], ['What goes on beat 1 in 3/4?', ['A bass note', 'A rest', 'A chop', 'A scale'], 0, 'Bass on 1.'], ['What should carry the song?', ['The words', 'The guitar solo', 'The loud strum', 'The capo'], 0, 'Serve the words.']]) },
  { id: 'g52', title: 'Playing with a drummer and bass', mins: 12, why: 'In a band the guitar fits in the gaps the others leave.', body: ['Listen to the kick drum and the bass guitar. Your strum should lock to the same beat and leave space for them.', 'Do not play every beat of every bar. Leave bars of rest, play fewer strings, and let the others shine.', 'Practise with the app: play along with each beat style and try to fit your strum to the drum.'], chords: ['G', 'D', 'Em', 'C'], jam: { chords: ['G', 'D', 'Em', 'C'], beat: 'afro', bpm: 96 }, play: ['Play along with the rock beat and lock with the kick', 'Play along with the Afrobeat beat', 'Leave out two beats in each bar and keep time'], apply: 'Play along with three different beats and note how your strum changes.', quiz: GQ([['What should you lock with?', ['The kick drum and bass', 'The loudest sound', 'Nothing', 'The tuner'], 0, 'The rhythm section.'], ['Why leave space?', ['So the others can be heard', 'To play slower', 'To save strings', 'To avoid practice'], 0, 'Space makes the band clear.'], ['Do you play every beat?', ['No, leave gaps', 'Yes always', 'Only on beat 1', 'Never'], 0, 'Fewer notes can sound better.']]) },
  { id: 'g53', title: 'Improvising over a progression', mins: 16, why: 'Improvising lets you create music in the moment.', body: ['Choose a scale that fits the key. For Am G F G use the A minor pentatonic. Play short phrases of two to four notes.', 'Repeat a phrase, then change one note. Repeating shapes your ideas into a tune.', 'Land on a chord tone (A, C or E for Am) on the first beat of each bar.'], chords: ['Am', 'G', 'F'], jam: { chords: ['Am', 'G', 'F', 'G'], beat: 'rock', bpm: 84 }, play: ['Play the A minor pentatonic over Am for four bars', 'Repeat a short phrase and change one note', 'Land on A, C or E on beat 1'], apply: 'Improvise for three minutes along with the app, then record the best phrase.', quiz: GQ([['Which scale fits Am G F G?', ['A minor pentatonic', 'F♯ blues only', 'C♯ major', 'None'], 0, 'It fits the key.'], ['What helps ideas sound like a tune?', ['Repeating a phrase and varying it', 'Never repeating', 'Playing fast', 'Changing scales every beat'], 0, 'Repetition builds a melody.'], ['Where should you land?', ['On a chord tone on beat 1', 'On a random note', 'Between frets', 'Muted'], 0, 'A, C or E over Am.']]) },
  { id: 'g54', title: 'Reading chord charts and Nashville numbers', mins: 12, why: 'A band chart is the language of every rehearsal.', body: ['A chord chart shows the chords over the words, with bar lines. A slash means keep playing the same chord for a beat.', 'Nashville numbers write the chord as a number (1, 4, 5, 6m), so the chart works in any key. Call out the key and read the numbers.', 'Practise reading a four-bar chart on the spot and playing it without stopping.'], chords: ['G', 'D', 'Em', 'C'], jam: { chords: ['G', 'D', 'Em', 'C'], beat: 'ballad', bpm: 66 }, play: ['Write a chart for G D Em C with bar lines', 'Write it again in Nashville numbers', 'Read the chart in the key of C and play it'], apply: 'Write a chart for a worship song you know using numbers.', quiz: GQ([['What do Nashville numbers allow?', ['Playing in any key', 'Faster tempo', 'Louder sound', 'Tuning'], 0, 'They transpose easily.'], ['What does a slash mean on a chart?', ['Keep playing the chord', 'Stop', 'Change key', 'Mute'], 0, 'Keep the same chord.'], ['How is 1–5–6m–4 in C?', ['C G Am F', 'C F G Am', 'C D E F', 'C Am F G'], 0, 'C, G, Am, F.']]) },
  { id: 'g55', title: 'Caring for your guitar and changing strings', mins: 12, why: 'A well-kept guitar stays in tune and sounds better.', body: ['Wipe the strings after playing. Keep the guitar away from heat and damp, and store it in a case or on a stand.', 'Change strings every one to three months. Remove one string at a time, thread the new one through the bridge, wind it on the peg, and tune it up. Stretch it gently and retune.', 'If the action (string height) is too high or the guitar buzzes, a repair shop can adjust it.'], play: ['Wipe your strings after practising', 'Watch how the strings are wound on a peg', 'Change one string and tune it up'], apply: 'Mark a date on your calendar to change the strings.', quiz: GQ([['How often should you change strings?', ['Every one to three months', 'Every day', 'Never', 'Every five years'], 0, 'Strings wear out.'], ['What should you do after changing a string?', ['Stretch it and retune', 'Leave it', 'Cut it', 'Tune it down'], 0, 'New strings go flat quickly.'], ['Where should you store a guitar?', ['Away from heat and damp', 'In the sun', 'In a car', 'Near a heater'], 0, 'Heat and damp warp wood.']]) },
  { id: 'g56', title: 'Practice routines that work', mins: 10, why: 'How you practise matters more than how long you practise.', body: ['Short, focused sessions beat long, unfocused ones. Practise 20 to 30 minutes a day with a plan.', 'A good session: tune and warm up (5 min), one new skill (10 min), a chord-change drill (5 min), a song (10 min). Use the Daily practice card in the app.', 'Track your progress. Write down the speed you reached and aim to beat it next time.'], play: ['Plan a 25-minute practice', 'Do the warm-up, new skill, drill and song', 'Write down your drill score'], apply: 'Practise for 25 minutes a day for one week and note the results.', quiz: GQ([['Which is better?', ['Short focused sessions', 'One huge weekly session', 'No plan', 'Only playing songs'], 0, 'Consistency builds skill.'], ['What belongs in a good session?', ['Warm-up, new skill, drill and a song', 'Only songs', 'Only scales', 'Only tuning'], 0, 'A balanced plan.'], ['Why track your progress?', ['To beat it next time', 'To avoid practice', 'To change guitars', 'To impress others'], 0, 'Measurable goals motivate.']]) },
  { id: 'g57', title: 'Capstone III: arrange and lead a full set', mins: 40, why: 'The final test of everything you have learned.', body: ['Choose four songs. Arrange each with a different style: fingerstyle ballad, gospel shuffle, highlife, and a fast praise. Write each as a chart in Nashville numbers.', 'Lead the set: count in, keep steady time, use dynamics, play one lead phrase, and finish with an amen cadence.', 'Record the set, listen back, and write down three things you did well and two things to improve.'], chords: ['G', 'D', 'Em', 'C'], jam: { chords: ['G', 'D', 'Em', 'C'], beat: 'praise', bpm: 110 }, play: ['Write the four charts', 'Rehearse each song and the transitions', 'Play the full set and record it'], apply: 'Perform the set for the club or a friend and ask for feedback.', quiz: GQ([['What should you write for each song?', ['A chart in numbers', 'Only the title', 'Nothing', 'A new capo'], 0, 'Charts make the set easy to lead.'], ['What do you finish with?', ['An amen cadence', 'A tuning', 'Silence only', 'A scale'], 0, 'IV to I.'], ['What do you do after recording?', ['Listen back and note strengths and fixes', 'Delete it', 'Never listen', 'Play louder'], 0, 'Reflect to improve.']]) }
];
