let gT = null, gScore = {};
function gStop() { if (gT) { clearInterval(gT.iv); gT = null; } gJam = null; Snd.stopAll(); if (typeof MicChords !== 'undefined') MicChords.stop(); }
function gPracticeCard(st) {
  const nextL = GUITAR.find(x => !(st[x.id] || {}).done), drs = GUITAR.filter(x => x.drill), dl = drs.filter(x => (st[x.id] || {}).done).sort((a, b) => ((st[a.id].drill || 0) / a.drill.target) - ((st[b.id].drill || 0) / b.drill.target))[0] || drs[0], e = st.ear || { n: 0, ok: 0 };
  return '<section class="card"><h3>Daily practice</h3><div class="row wrap">' + (nextL ? '<button class="btn primary sm" type="button" data-act="gopen" data-id="' + nextL.id + '">Continue: ' + esc(nextL.title) + '</button>' : '') + '<button class="btn ghost sm" type="button" data-act="gopen" data-id="' + dl.id + '">Chord-change drill: ' + esc(dl.drill.a) + ' ↔ ' + esc(dl.drill.b) + '</button><button class="btn ghost sm" type="button" data-act="gearopen">Ear training' + (e.n ? ' (' + e.ok + '/' + e.n + ')' : '') + '</button><button class="btn ghost sm" type="button" data-act="gtunopen">Guitar tuner</button></div></section>';
}
function guitarCourseBody() {
  const st = gst(), q = (ui.courseQ || '').trim().toLowerCase(), unfin = !!ui.courseUnfinished;
  const keep = id => { const x = GUITAR.find(y => y.id === id); return x && (!unfin || !gDone(id)) && (!q || x.title.toLowerCase().indexOf(q) >= 0); };
  const mods = GMODS.map((m, mi) => [m[0], m[1].filter(keep), mi]).filter(m => m[1].length);
  if (!mods.length) return '<section class="card"><p class="muted">No guitar lessons match.</p><button class="btn ghost sm" type="button" data-act="cclear">Clear</button></section>';
  return mods.map(m => '<section class="card"><h3>' + esc(m[0]) + '</h3><ul class="lessons">' + m[1].map(id => { const x = GUITAR.find(y => y.id === id), r = st[id] || {}; const un = gUnlocked(id), prev = gOrder()[gOrder().indexOf(id) - 1], px = prev ? GUITAR.find(y => y.id === prev) : null; return '<li class="lrow' + (un ? (r.done ? ' done' : '') : ' locked') + '"><span class="lstat">' + (!un ? icon('lock') : r.done ? icon('star') : '<i class="ring"></i>') + '</span><div class="lmain"><b>' + esc(x.title) + '</b><span class="tiny">' + x.mins + ' min' + (r.best ? ' · best ' + r.best + '%' : '') + (!un && px ? ' · Finish “' + esc(px.title) + '” first' : '') + '</span></div><button class="btn sm ' + (un && !r.done ? 'primary' : 'ghost') + '" type="button" data-act="gopen" data-id="' + id + '"' + (un ? '' : ' disabled') + '>' + (!un ? 'Locked' : r.done ? 'Review' : 'Start') + '</button></li>'; }).join('') + '</ul><button class="btn ghost sm" type="button" data-act="gtest" data-m="' + m[2] + '">Module test-out</button></section>').join('');
}
function viewGuitar() {
  const st = gst(), lid = (route.params || {}).lid, L = gFind(lid);
  if ((route.params || {}).tuner) return viewGTuner();
  if ((route.params || {}).ear) return viewGEar();
  if (!L) {
    const done = gDoneCount();
    ui.courseTab = 'guitar';
    return { html: '<div class="screen">' + courseTabs('guitar') + '<div class="pagehead"><h1>Guitar course</h1><p class="muted">' + done + ' of ' + gOrder().length + ' lessons done. Score 80% or more on each quiz to finish a lesson; each lesson unlocks the next. Already play? Pass a module test to skip ahead.</p></div>' + gPracticeCard(st) + courseSearch('guitar') + '<div id="cresults">' + guitarCourseBody() + '</div>' + '</div>' };
  }
  if (L.id[0] !== 'T' && !gUnlocked(L.id)) return { html: '<div class="screen"><div class="card"><h2>' + esc(L.title) + ' is locked</h2><p>Finish the lesson before it, or pass the module test, to open this one.</p><button class="btn primary" type="button" data-act="gback">Back to the guitar course</button></div></div>' };
  gScore[L.id] = {}; const r = st[L.id] || {}, chk = r.chk || {};
  const html = '<div class="screen"><div class="pagehead"><button class="btn ghost sm" type="button" data-act="gback">' + icon('back') + 'Guitar course</button><h1>' + esc(L.title) + '</h1><p class="muted">' + esc(L.why) + '</p>' + (L.goal ? '<p><b>Goal:</b> ' + esc(L.goal) + '</p>' : '') + '</div>' +
    '<section class="card"><h3>1. Theory</h3>' + L.body.map(p => '<p>' + esc(p) + '</p>').join('') + (L.tab ? '<pre class="mono" style="overflow:auto;padding:.5rem">' + esc(L.tab.join('\n')) + '</pre>' : '') + '</section>' +
    (L.listen || L.notes ? '<section class="card"><h3>2. Listen</h3><button class="btn ghost" type="button" data-act="gnotes" data-id="' + L.id + '">' + icon('play') + (L.notes ? 'Play the scale' : 'Play the open strings') + '</button></section>' : '') +
    (L.chords ? '<section class="card"><h3>2. See the shapes</h3><p class="muted">Tap a chord to hear it. × means do not play that string, ○ means open.</p><div class="row wrap" style="gap:.8rem">' + L.chords.map(c => '<button type="button" class="btn ghost" style="flex-direction:column;height:auto;padding:.4rem" data-act="gchord" data-c="' + c + '">' + gChordSvg(c) + '</button>').join('') + '</div>' + L.chords.slice(0, 4).map(c => '<details><summary>Step by step: ' + esc(c) + '</summary><ol class="tiny">' + gWalk(c) + '</ol><button class="btn ghost sm" type="button" data-act="gpick" data-c="' + c + '">Hear each string</button></details>').join('') + micCheckHtml(L) + '</section>' : '') +
    (L.play ? '<section class="card"><h3>3. Play</h3>' + L.play.map((t, i) => '<label class="switch"><input type="checkbox" data-act="gchk" data-id="' + L.id + '" data-i="' + i + '"' + (chk[i] ? ' checked' : '') + '><span>' + esc(t) + '</span></label>').join('') + '</section>' : '') +
    (L.jam ? '<section class="card"><h3>4. Strum along</h3><p class="muted">' + L.jam.chords.map(esc).join(' – ') + ' · ' + L.jam.bpm + ' BPM · ' + esc(E.BEATS[L.jam.beat].label) + (L.jam.arp ? ' · fingerpicking pattern' : '') + '</p><p class="tiny">Slow: 75% speed. Target: full speed. Challenge: 125% speed, from memory without looking at the diagrams.</p><div class="row wrap">' + [['Slow', 0.75], ['Target', 1], ['Challenge', 1.25]].map(x => '<button class="btn ' + (x[1] === 1 ? 'primary' : 'ghost') + '" type="button" data-act="gjam" data-id="' + L.id + '" data-f="' + x[1] + '" data-label="' + x[0] + '">' + icon('play') + x[0] + '</button>').join('') + '</div></section>' : '') +
    (L.drill ? '<section class="card gdr"><h3>5. One-minute chord-change drill</h3><p class="muted">Change between ' + esc(L.drill.a) + ' and ' + esc(L.drill.b) + ' with the click. Tap the big button each time you land a clean change. Target: ' + L.drill.target + '. ' + (r.drill ? 'Your best: ' + r.drill + '.' : '') + '</p><p><b class="gtime mono">60</b> s · <b class="gcount mono">0</b> changes</p><div class="row wrap"><button class="btn primary" type="button" data-act="gdrill" data-id="' + L.id + '">Start 60 seconds</button><button class="btn ghost lg" type="button" data-act="gtick" disabled>I changed</button></div>' + (MicChords.supported ? '<label class="switch"><input type="checkbox" id="gdrillmic"' + (ui.gDrillMic ? ' checked' : '') + '><span>Count my changes by listening (microphone)</span></label>' : '') + '<p class="tiny gres" aria-live="polite"></p></section>' : '') +
    '<section class="card"><h3>' + (L.drill ? 6 : 5) + '. Quiz</h3>' + L.quiz.map((qq, qi) => '<div class="gqq"><p><b>' + esc(qq.q) + '</b></p><div class="row wrap">' + qq.o.map((o, oi) => '<button class="btn ghost sm" type="button" data-act="gans" data-id="' + L.id + '" data-qi="' + qi + '" data-oi="' + oi + '">' + esc(o) + '</button>').join('') + '</div><p class="tiny gfb" aria-live="polite"></p></div>').join('') + '<p id="gsum" class="tiny" aria-live="polite"></p><button class="btn ghost" type="button" id="gretry" hidden data-act="gopen" data-id="' + L.id + '">Retry the quiz</button></section>' +
    (L.apply ? '<section class="card"><h3>Apply</h3><p>' + esc(L.apply) + '</p></section>' : '') +
    '<section class="card"><button class="btn primary lg" type="button" id="gdonebtn" data-act="gdone" data-id="' + L.id + '"' + (r.done ? '' : ' disabled') + '>' + (r.done ? 'Done ✓ Back to the list' : 'Finish lesson (pass the quiz first)') + '</button></section></div>';
  return { html, mount(root) { mountMicCheck(root, L); return () => { gStop(); MicChords.stop(); }; } };
}
/* ---- checking chords through the microphone ---- */
function micCheckHtml(L) {
  if (!MicChords.supported) return '';
  return '<div class="miccheck"><p class="eyebrow">Check with the microphone</p><p class="tiny">Hold the guitar near the computer, strum each chord and let it ring. The app listens and ticks it off. Works best in a quiet room.</p>' +
    '<div class="row wrap" id="micchords">' + L.chords.map(c => '<span class="pill chord" data-c="' + esc(c) + '">' + esc(c) + '</span>').join('') + '</div>' +
    '<div class="miclevel" aria-hidden="true"><i id="miclvl"></i></div><p class="tiny" id="micmsg" aria-live="polite"></p>' +
    '<button class="btn primary sm" type="button" id="micgo">Start listening</button></div>';
}
function mountMicCheck(root, L) {
  const go = $('#micgo', root);
  if (go && L.chords) {
    let i = 0;
    const pills = () => $$('#micchords .pill', root), msg = $('#micmsg', root), lvl = $('#miclvl', root);
    const mark = () => pills().forEach((p, k) => { p.classList.toggle('done', k < i); p.classList.toggle('cur', k === i); });
    const watch = chordWatcher(() => [L.chords[i]], name => {
      i++; mark();
      if (i >= L.chords.length) { MicChords.stop(); go.textContent = 'Check again'; msg.textContent = 'All ' + L.chords.length + ' chords heard clearly.'; const r = (gst()[L.id] = gst()[L.id] || {}); r.mic = (r.mic || 0) + 1; touch(); }
      else msg.textContent = 'Heard ' + name + '. Now play ' + L.chords[i] + '.';
    }, e => { if (lvl) lvl.style.width = Math.min(100, Math.round(e * 900)) + '%'; });
    go.addEventListener('click', async () => {
      if (MicChords.on) { MicChords.stop(); go.textContent = 'Start listening'; msg.textContent = ''; return; }
      i = 0; mark();
      try { await MicChords.start(watch); go.textContent = 'Stop listening'; msg.textContent = 'Play ' + L.chords[0] + '.'; }
      catch (e) { msg.textContent = 'The microphone could not be opened. Check that it is connected and that no other program is using it.'; }
    });
  }
  const box = $('#gdrillmic', root);
  if (box) box.addEventListener('change', () => { ui.gDrillMic = box.checked; });
}
